    <style>
        *{box-sizing:border-box}body{margin:0;background:#f1f5f2;color:#17211c;font:13px/1.5 Arial,sans-serif}.sheet{max-width:1200px;margin:28px auto;padding:32px;background:#fff}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:20px}.eyebrow{color:#567765;font-size:11px;font-weight:bold;letter-spacing:.12em;text-transform:uppercase}h1{margin:5px 0 4px;font-size:24px}.muted{color:#65716b}.actions{display:flex;gap:8px}.actions button{border:0;border-radius:8px;background:#567765;color:#fff;padding:10px 14px;font-weight:bold;cursor:pointer}.meta{display:flex;gap:24px;margin:22px 0;padding:14px 0;border-top:1px solid #dfe6e1;border-bottom:1px solid #dfe6e1}.meta strong{display:block;margin-top:3px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #d8dfda;padding:8px;text-align:left;vertical-align:top}th{background:#eff4ef;font-size:11px;text-transform:uppercase;letter-spacing:.04em}tbody tr:nth-child(even){background:#fafcfb}.footer{margin-top:18px;color:#65716b;font-size:11px}@media print{body{background:#fff;font-size:10px}.sheet{max-width:none;margin:0;padding:0}.actions{display:none}th,td{padding:5px;print-color-adjust:exact;-webkit-print-color-adjust:exact}@page{size:landscape;margin:12mm}}
