<body><main class="sheet">
    <div class="top"><div><div class="eyebrow">HadirKantor · Laporan</div><h1>Pengajuan Izin Karyawan</h1><div class="muted">Periode pengajuan: {{ \Illuminate\Support\Carbon::parse($filters['from'])->translatedFormat('d M Y') }} – {{ \Illuminate\Support\Carbon::parse($filters['to'])->translatedFormat('d M Y') }}</div></div><div class="actions"><button type="button" onclick="window.print()">Cetak / Simpan PDF</button></div></div>
